#include <vector>
#include <unordered_set>
#include <set>

using namespace std;

class Solution {
public:
    int subarrayBitwiseORs(vector<int>& A) {
        unordered_set<int> res;
        set<int> cur;
        for (int a : A) {
            set<int> nxt = {a};
            for (int x : cur)
                nxt.insert(x | a);
            cur = nxt;
            res.insert(cur.begin(), cur.end());
        }
        return res.size();
    }
};
